class Solution {
  private long[][] bit;
  private int n;

  private void add(int d, int i, int v) {
    for (i++; i <= n; i += i & -i) bit[d][i] += v;
  }

  private long sum(int d, int i) {
    long s = 0;
    for (i++; i > 0; i -= i & -i) s += bit[d][i];
    return s;
  }

  private static int depthOf(long x) {
    int d = 0;
    while (x != 1) {
      x = Long.bitCount(x);
      d++;
    }
    return d;
  }

  public int[] popcountDepth(long[] nums, long[][] queries) {
    n = nums.length;
    bit = new long[6][n + 1];
    int[] depth = new int[n];
    for (int i = 0; i < n; i++) {
      depth[i] = depthOf(nums[i]);
      add(depth[i], i, 1);
    }
    int cnt = 0;
    for (long[] q : queries) if (q[0] == 1) cnt++;
    int[] ans = new int[cnt];
    int idx = 0;
    for (long[] q : queries) {
      if (q[0] == 1) {
        int d = (int) q[3];
        ans[idx++] = (int) (sum(d, (int) q[2]) - sum(d, (int) q[1] - 1));
      } else {
        int i = (int) q[1];
        add(depth[i], i, -1);
        depth[i] = depthOf(q[2]);
        add(depth[i], i, 1);
      }
    }
    return ans;
  }
}
